import re
from decimal import Decimal

MAX_CENTS = 100_000_000  # 1000000.00

# Plain decimal: optional sign, digits with optional fraction. No whitespace, no exponent.
_PLAIN_DECIMAL = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)")


def _cents_from_decimal(value):
    """Exact conversion of a finite Decimal to integer cents.

    Uses only the Decimal tuple representation and integer arithmetic, so the
    global decimal context is never consulted or modified.
    """
    if not value.is_finite():
        raise ValueError("amount must be finite")
    sign, digits, exp = value.as_tuple()
    if not any(digits):
        raise ValueError("amount must be greater than zero")
    # Any nonzero value with adjusted exponent >= 7 is above the maximum;
    # any nonzero value below 0.001 is not representable in cents.
    # Checking these first keeps the integer arithmetic below bounded.
    adjusted = value.adjusted()
    if adjusted >= 7:
        raise ValueError("amount exceeds 1000000.00")
    if adjusted <= -3:
        raise ValueError("amount is not exactly representable in cents")
    if sign:
        raise ValueError("amount must be greater than zero")
    n = int("".join(map(str, digits)))
    shift = exp + 2  # value in cents = n * 10**shift
    if shift >= 0:
        cents = n * 10 ** shift
    else:
        divisor = 10 ** (-shift)
        if n % divisor:
            raise ValueError("amount is not exactly representable in cents")
        cents = n // divisor
    return cents


def _check_cents(cents):
    if cents <= 0:
        raise ValueError("amount must be greater than zero")
    if cents > MAX_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def _to_cents(value):
    """Validate an amount and return it as integer cents (1..MAX_CENTS)."""
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(value, int):
        return _check_cents(value * 100)
    if isinstance(value, Decimal):
        return _check_cents(_cents_from_decimal(value))
    if isinstance(value, str):
        if not _PLAIN_DECIMAL.fullmatch(value):
            raise ValueError("amount must be a plain decimal string")
        return _check_cents(_cents_from_decimal(Decimal(value)))
    raise ValueError(f"unsupported amount type: {type(value).__name__}")


def _cents_to_decimal(cents):
    """Build a Decimal with exponent -2 from integer cents, without context use."""
    digits = tuple(int(c) for c in str(cents))
    return Decimal((0, digits, -2))


def parse_amount(value):
    """Parse and validate a money amount, returning a Decimal with exponent -2."""
    return _cents_to_decimal(_to_cents(value))


def format_amount(value):
    return format(value, ".2f")
EOF
