from .money import _to_cents, _cents_to_decimal, _check_cents, format_amount


def make_invoice(amounts):
    # Materialize once; never modify the caller's input.
    items = list(amounts)
    total = 0
    for item in items:
        total += _to_cents(item)
    _check_cents(total) if total else None
    if total > 100_000_000:
        raise ValueError("total exceeds 1000000.00")
    return {"total": format_amount(_cents_to_decimal(total)), "count": len(items)}
